function frame(t, p, d) {
  const tf = Math.min(t, d * 0.55);

  cards.forEach((el, i) => {
    const s = spr(tf, i * 0.6, 0.85, 8);
    el.style.opacity = clamp(s * 2);
    const y = lerp(40, 0, E_OUT(clamp(s)));
    const scale = lerp(0.9, 1, E_OUT(clamp(s)));
    el.style.transform = `translateY(${y}px) scale(${scale})`;
  });

  lines.forEach((l, i) => {
    const s = spr(tf, 0.4 + i * 0.6, 0.9, 7);
    l.el.style.strokeDashoffset = l.len * (1 - s);
    l.el.style.opacity = s;
  });

  const ss = spr(tf, 2.4, 0.8, 6);
  stars.style.opacity = ss;
  stars.style.transform = `translateY(${lerp(30, 0, E_OUT(ss))}px)`;
}
